import { showDevNav } from '../dev/isStandalone';

/** Error page paths that are exempt from permission checks to prevent redirect loops. */
export const HOME_ERROR_PATHS = [
  'forbidden',
  'not-found',
  'session-expired',
] as const;

/** Route prefixes owned by @linm/web-home — keep in sync with mfe.routes.json */
const HOME_ROUTE_PREFIXES = [
  'login',
  'logout',
  'settings',
  'notifications',
  'messages',
  'tra-cuu-tk',
  'phong-ban',
  'nhan-vien',
  'help',
  'faq',
  'contact',
  'install-guide',
  'notification-guide',
  ...HOME_ERROR_PATHS,
] as const;

function normalizePathname(pathname: string): string {
  if (!pathname) return '/';
  if (pathname.length > 1 && pathname.endsWith('/')) {
    return pathname.slice(0, -1);
  }
  return pathname;
}

/** True when path should be handled inside Home MemoryRouter (not another MFE). */
export function isHomeShellPath(pathname: string): boolean {
  const path = normalizePathname(pathname);
  if (path === '/') return true;
  if (showDevNav && (path === '/dev' || path.startsWith('/dev/'))) return true;
  return HOME_ROUTE_PREFIXES.some(
    (prefix) => path === `/${prefix}` || path.startsWith(`/${prefix}/`),
  );
}
