import React, { useEffect } from 'react';
import { Navigate, useLocation, useNavigate } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';
import { UserRole } from '../../models/User';
import {
  getHomePath,
  isPathAllowed,
  hasValidAuthToken,
  usePermissionsReady,
  PermissionsBootstrapLoading,
} from '@linm-soft-org/linm-web-common-components';
import { isHomeDevAuthBypass } from '../../dev/isHomeDevAuthBypass';
import { AuthLoginRedirect } from './AuthLoginRedirect';
import { navigateInAppPath } from '../../router/navigateInAppPath';
import { isStandalone } from '../../dev/isStandalone';
import { HOME_ERROR_PATHS } from '../../router/homeShellRoutes';

interface ProtectedRouteProps {
  children: React.ReactNode;
  allowedRoles?: UserRole[];
}

function isErrorPath(pathname: string): boolean {
  return HOME_ERROR_PATHS.some(
    (prefix) => pathname === `/${prefix}` || pathname.startsWith(`/${prefix}/`),
  );
}

const ERR_SESSION_KEY = 'linm:error:original-path';

function saveOriginalPath(pathname: string): void {
  try { sessionStorage.setItem(ERR_SESSION_KEY, pathname); } catch { /* noop */ }
}

export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({
  children,
  allowedRoles,
}) => {
  const navigate = useNavigate();
  const { isAuthenticated, user } = useAppSelector((state) => state.auth);
  const location = useLocation();
  const permissionsReady = usePermissionsReady();
  const devBypass = isHomeDevAuthBypass();

  const homePath =
    location.pathname === '/'
      ? getHomePath(
          user?.role,
          user?.package,
          user?.defaultMenuUrl,
          user?.packageDefaultUrl,
        )
      : null;

  useEffect(() => {
    if (devBypass || location.pathname !== '/' || !homePath || homePath === '/') return;
    navigateInAppPath(homePath, navigate, { replace: true });
  }, [devBypass, location.pathname, homePath, navigate]);

  if (!devBypass && (!isAuthenticated || !hasValidAuthToken())) {
    return <AuthLoginRedirect />;
  }

  if (!devBypass && !permissionsReady) {
    return <PermissionsBootstrapLoading />;
  }

  if (!devBypass && location.pathname === '/' && homePath && homePath !== '/') {
    if (isStandalone) {
      return <Navigate to={homePath} replace />;
    }
    return null;
  }

  if (allowedRoles && allowedRoles.length > 0 && user) {
    if (!allowedRoles.includes(user.role)) {
      saveOriginalPath(location.pathname);
      return <Navigate to="/forbidden" replace />;
    }
  }

  // Skip isPathAllowed for known error pages to prevent infinite redirect loop.
  // These paths are explicitly routed inside the Home MFE and should always
  // be accessible to authenticated users regardless of permission navItems.
  if (!isErrorPath(location.pathname) && !devBypass && user && !isPathAllowed(user.role, user.package, location.pathname)) {
    saveOriginalPath(location.pathname);
    return <Navigate to="/forbidden" replace />;
  }

  return <>{children}</>;
};
