import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { clearPermissionsCache, linmLogo128 } from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { logout } from '../../store/slices/authSlice';
import { navigateInAppPath } from '../../router/navigateInAppPath';
import { resolveShellIcon } from '../../config/shellBranding';
import styles from './ShellLogoutHandler.module.css';

const AUTH_RETURN_URL_KEY = 'linm:auth:return-url';

declare global {
  interface Window {
    __LINM_LOGOUT_IN_PROGRESS__?: boolean;
  }
}

/**
 * Runs shell logout when the browser URL is /logout — independent of MemoryRouter
 * matching (Home remount can leave memory router on a stale path).
 *
 * Global guard window.__LINM_LOGOUT_IN_PROGRESS__ prevents the Root shell from
 * racing the logout thunk by clearing tokens before the backend call completes.
 */
export const ShellLogoutHandler: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const startedRef = useRef(false);
  const logoutLoading = useAppSelector((state) => state.auth.logoutLoading);
  const [visible, setVisible] = useState(
    () => typeof window !== 'undefined' && window.location.pathname === '/logout',
  );

  useEffect(() => {
    const tryLogout = () => {
      const onLogoutPath = window.location.pathname === '/logout';
      if (!onLogoutPath) {
        startedRef.current = false;
        window.__LINM_LOGOUT_IN_PROGRESS__ = false;
        setVisible(false);
        return;
      }

      setVisible(true);
      if (startedRef.current) return;
      startedRef.current = true;
      window.__LINM_LOGOUT_IN_PROGRESS__ = true;

      sessionStorage.removeItem(AUTH_RETURN_URL_KEY);
      clearPermissionsCache();

      void dispatch(logout()).finally(() => {
        // Notify cross-tab listeners (root-config) that logout is complete,
        // so other tabs can reload to /login without racing the API call.
        window.dispatchEvent(new CustomEvent('linm:logout:complete'));
        window.__LINM_LOGOUT_IN_PROGRESS__ = false;
        navigateInAppPath('/login', navigate, { replace: true });
      });
    };

    tryLogout();
    window.addEventListener('single-spa:routing-event', tryLogout);
    window.addEventListener('popstate', tryLogout);
    return () => {
      window.removeEventListener('single-spa:routing-event', tryLogout);
      window.removeEventListener('popstate', tryLogout);
    };
  }, [dispatch, navigate]);

  if (!visible) return null;

  return (
    <div className={styles.container} role="status" aria-live="polite" aria-busy="true">
      <div className={styles.stage} aria-hidden="true">
        <img
          src={resolveShellIcon(linmLogo128)}
          alt=""
          className={styles.logo}
          width={64}
          height={64}
          onError={(e) => {
            const img = e.currentTarget;
            if (img.src !== linmLogo128) img.src = linmLogo128;
          }}
        />
      </div>
      <p className={styles.label}>
        {logoutLoading ? 'Đang đăng xuất...' : 'Đã đăng xuất'}
      </p>
    </div>
  );
};

export default ShellLogoutHandler;
