import React, { useEffect, useRef } from 'react';
import type { Parcel } from 'single-spa';
import {
  mountParcel,
  unmountParcel,
  type ParcelLinkConfig,
} from '@linm-soft-org/linm-web-common-components';

export interface AdminOrgCatalogParcelHostProps {
  link: ParcelLinkConfig;
  customProps?: Record<string, unknown>;
}

/** Mount org catalog UI from @linm/admin parcel (departments / employees). */
export const AdminOrgCatalogParcelHost: React.FC<AdminOrgCatalogParcelHostProps> = ({
  link,
  customProps,
}) => {
  const hostRef = useRef<HTMLDivElement>(null);
  const parcelRef = useRef<Parcel | null>(null);
  const customPropsRef = useRef(customProps);
  customPropsRef.current = customProps;

  useEffect(() => {
    let cancelled = false;
    const host = hostRef.current;
    if (!host) return;

    const timer = setTimeout(() => {
      mountParcel({
        link,
        domElement: host,
        customProps: customPropsRef.current ?? {},
      })
        .then((p) => {
          if (cancelled) {
            void unmountParcel(p);
            return;
          }
          parcelRef.current = p;
        })
        .catch((err) => {
          console.warn('[AdminOrgCatalogParcelHost]', link.exportName, err);
        });
    }, 0);

    return () => {
      cancelled = true;
      clearTimeout(timer);
      void unmountParcel(parcelRef.current);
      parcelRef.current = null;
    };
  }, [link]);

  return <div ref={hostRef} style={{ height: '100%' }} />;
};
