type PlatformTab = 'android' | 'ios' | 'chrome-desktop' | 'edge-desktop';
type GuideStep = { title: string; desc: string; code?: string };

function detectPlatform(): PlatformTab {
  if (typeof navigator === 'undefined') return 'chrome-desktop';
  const ua = navigator.userAgent;
  if (/iPhone|iPad|iPod/.test(ua)) return 'ios';
  if (/Android/.test(ua)) return 'android';
  if (/Edg\//.test(ua)) return 'edge-desktop';
  return 'chrome-desktop';
}

function isIOSDevice(): boolean {
  if (typeof navigator === 'undefined') return false;
  return /iPhone|iPad|iPod/.test(navigator.userAgent);
}

