export const InstallAppGuidePage: React.FC = () => {
  const appName = resolveAppName();
  useNavTitle(`Cài đặt Ứng dụng ${appName}`);
  const navigate = useNavigate();
  const { isInstallable, isInstalled, isStandalone, promptInstall } = useInstallPrompt();
  const [platform, setPlatform] = useState<PlatformTab>(detectPlatform);
  const [showGuide, setShowGuide] = useState(false);
  const [installDone, setInstallDone] = useState(false);
  const isIOS = isIOSDevice();
  const { steps: stepData, troubleshoot: troubleshootRows } = buildGuideContent(appName);

  // Sync platform tab when beforeinstallprompt fires (Android Chrome)
  useEffect(() => {
    if (isInstallable && platform !== 'android') {
      const ua = navigator.userAgent;
      if (/Android/.test(ua)) setPlatform('android');
    }
  }, [isInstallable, platform]);

  // Single handler for the install button on every platform
  const handleInstallClick = async () => {
    if (isInstallable) {
      const accepted = await promptInstall();
      if (accepted) {
        setInstallDone(true);
      } else {
        // User dismissed the native dialog — show manual guide as fallback
        setShowGuide(true);
      }
    } else {
      // iOS / Firefox — toggle inline guide
      setShowGuide(prev => !prev);
    }
  };

  const steps = stepData[platform];

  // ── Section 1 content ─────────────────────────────────────────────────────
  const renderQuickInstall = () => {
    // Already running inside the PWA window
    if (isStandalone) {
      return (
        <div className={styles.quickInstallState}>
          <div className={`${styles.stateIcon} ${styles.stateIconSuccess}`}>
            <i className="fas fa-check-circle" />
          </div>
          <div className={styles.stateBody}>
            <div className={styles.stateTitle}>Bạn đang dùng ứng dụng!</div>
            <div className={styles.stateDesc}>
              {appName} đang chạy dưới dạng ứng dụng độc lập — toàn màn hình, không có thanh địa chỉ.
            </div>
          </div>
        </div>
      );
    }

    // App installed, browsing in regular tab
    if (installDone || isInstalled) {
      const isMobileDevice = isIOS || /Android/.test(navigator.userAgent);
      return (
        <div className={styles.quickInstallState}>
          <div className={`${styles.stateIcon} ${styles.stateIconSuccess}`}>
            <i className="fas fa-check-circle" />
          </div>
          <div className={styles.stateBody}>
            <div className={styles.stateTitle}>Ứng dụng đã được cài đặt!</div>
            {isMobileDevice ? (
              <>
                <div className={styles.stateDesc}>
                  Để mở ứng dụng, tìm biểu tượng <strong>{appName}</strong> trên màn hình chính và nhấn vào đó.
                </div>
                <div className={styles.openTip}>
                  <i className="fas fa-hand-pointer" />
                  <span>Nhấn giữ biểu tượng → kéo ra vị trí dễ thấy nếu cần.</span>
                </div>
              </>
            ) : (
              <>
                <div className={styles.stateDesc}>
                  Để mở ứng dụng dưới dạng cửa sổ riêng, nhấn nút{' '}
                  <strong>«&thinsp;Open in app&thinsp;»</strong> trên thanh địa chỉ Chrome/Edge.
                </div>
                <div className={styles.openTip}>
                  <i className="fas fa-arrow-up" />
                  <span>Nút này nằm ở góc phải thanh địa chỉ — có biểu tượng màn hình máy tính.</span>
                </div>
              </>
            )}
          </div>
        </div>
      );
    }

    // ── Single install button for ALL platforms ──────────────────────────────
    // Chrome/Edge/Android → fires native browser prompt (same as browser button)
    // iOS/Firefox       → button expands inline step guide
    const isPromptReady = isInstallable;
    const btnLabel = isPromptReady
      ? 'Cài đặt ứng dụng'
      : showGuide
      ? 'Ẩn hướng dẫn'
      : 'Cài đặt ứng dụng';

    return (
      <div className={styles.singleInstallCard}>
        {/* Main CTA button */}
        <button
          type="button"
          className={styles.singleInstallBtn}
          onClick={handleInstallClick}
        >
          <i className={isPromptReady ? 'fas fa-download' : showGuide ? 'fas fa-chevron-up' : 'fas fa-download'} />
          <span>{btnLabel}</span>
        </button>

        {/* Context hint under the button */}
        {!showGuide && (
          <div className={styles.installHint}>
            {isPromptReady
              ? <><i className="fas fa-bolt" /> Nhấn để cài đặt ngay — không cần App Store hay Play Store.</>  
              : isIOS
              ? <><i className="fab fa-apple" /> Nhấn để xem hướng dẫn cài đặt trên iPhone / iPad.</>  
              : <><i className="fas fa-info-circle" /> Nhấn để xem hướng dẫn cài đặt thủ công.</>  
            }
          </div>
        )}

        {/* Inline guide — expands when user can't use native prompt */}
        {showGuide && (
          <div className={styles.inlineGuide}>
            {isIOS ? (
              <ol className={styles.inlineSteps}>
                <li>
                  Nhấn nút <strong>Chia sẻ</strong>{' '}
                  <span className={styles.iosIcon}><i className="fas fa-share-square" /></span>{' '}
                  ở thanh dưới Safari
                </li>
                <li>Cuộn xuống, chọn <strong>"Thêm vào màn hình chính"</strong></li>
                <li>Nhấn <strong>"Thêm"</strong> để hoàn tất</li>
              </ol>
            ) : (
              <ol className={styles.inlineSteps}>
                <li>Nhấn biểu tượng <strong>⊕</strong> trên thanh địa chỉ trình duyệt</li>
                <li>Hoặc vào menu <strong>⋮ → Cài đặt ứng dụng / Install app</strong></li>
                <li>Xác nhận trong hộp thoại xuất hiện</li>
              </ol>
            )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className={styles.page}>
      {/* Breadcrumb + Title */}
      <div className={styles.header}>
        <nav className={styles.breadcrumb}>
          <button className={styles.breadcrumbLink} onClick={() => navigate('/help')}>
            <i className="fas fa-life-ring" /> Trợ giúp
          </button>
          <i className="fas fa-chevron-right" />
          <span>Hướng dẫn cài đặt ứng dụng</span>
        </nav>
        <h1 className={styles.title}>
          <i className={`fas fa-mobile-alt ${styles.titleIcon}`} />
          Cài đặt Ứng dụng {appName}
        </h1>
        <p className={styles.subtitle}>
          Cài đặt {appName} lên thiết bị của bạn để truy cập nhanh hơn, nhận thông báo đẩy và sử dụng toàn màn hình như ứng dụng native.
        </p>
      </div>

      {/* ═══════════════════════════════════════════════════════════════════
          PHẦN 1 — CÀI ĐẶT NHANH
      ═══════════════════════════════════════════════════════════════════ */}
      <div className={styles.sectionCard}>
        <div className={styles.sectionHeader}>
          <span className={styles.sectionBadge}>Phần 1</span>
          <i className={`fas fa-bolt ${styles.sectionHeaderIcon}`} />
          <h2 className={styles.sectionTitle}>Cài đặt nhanh</h2>
        </div>
        <div className={styles.sectionBody}>
          {renderQuickInstall()}

          {/* Benefits mini-row */}
          <div className={styles.benefitsRow}>
            {[
              { icon: 'fas fa-bolt',       text: 'Truy cập nhanh từ màn hình chính' },
              { icon: 'fas fa-bell',       text: 'Nhận thông báo đẩy khi đóng trình duyệt' },
              { icon: 'fas fa-expand',     text: 'Giao diện toàn màn hình, không có thanh địa chỉ' },
              { icon: 'fas fa-wifi-slash', text: 'Hoạt động offline khi mất mạng' },
            ].map((b) => (
              <div key={b.text} className={styles.benefitChip}>
                <i className={`${b.icon} ${styles.benefitChipIcon}`} />
                <span>{b.text}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ═══════════════════════════════════════════════════════════════════
          PHẦN 2 — HƯỚNG DẪN CÀI ĐẶT THỦ CÔNG
      ═══════════════════════════════════════════════════════════════════ */}
      <div className={styles.sectionCard}>
        <div className={styles.sectionHeader}>
          <span className={styles.sectionBadge}>Phần 2</span>
          <i className={`fas fa-list-ol ${styles.sectionHeaderIcon}`} />
          <h2 className={styles.sectionTitle}>Hướng dẫn cài đặt thủ công</h2>
        </div>
        <div className={styles.sectionBody}>
          {/* Platform tabs */}
          <div className={styles.platformTabs}>
            {PLATFORMS.map((p) => (
              <button
                key={p.id}
                className={`${styles.platformTab} ${platform === p.id ? styles.platformTabActive : ''}`}
                onClick={() => setPlatform(p.id)}
              >
                <i className={p.icon} /> {p.label}
              </button>
            ))}
          </div>

          {platform === 'ios' && (
            <div className={`${styles.alertBox} ${styles.alertWarning}`}>
              <i className={`fas fa-exclamation-triangle ${styles.alertIcon}`} />
              <span>
                Trên iPhone/iPad, <strong>chỉ Safari</strong> hỗ trợ "Add to Home Screen". Các trình duyệt khác (Chrome, Firefox trên iOS) không thể cài PWA.
              </span>
            </div>
          )}

          {(platform === 'chrome-desktop' || platform === 'edge-desktop') && (
            <div className={`${styles.alertBox} ${styles.alertInfo}`}>
              <i className={`fas fa-info-circle ${styles.alertIcon}`} />
              <span>
                Nếu thấy nút <strong>"Tải ứng dụng"</strong> ở góc trên trang, nhấn vào đó để cài đặt nhanh mà không cần qua menu trình duyệt.
              </span>
            </div>
          )}

          <div className={styles.steps}>
            {steps.map((step, idx) => (
              <div key={idx} className={styles.step}>
                <div className={styles.stepNumber}>{idx + 1}</div>
                <div className={styles.stepContent}>
                  <p className={styles.stepTitle}>{step.title}</p>
                  <p className={styles.stepDesc}>{step.desc}</p>
                  {step.code && <code className={styles.stepCode}>{step.code}</code>}
                </div>
              </div>
            ))}
          </div>

          {/* After-install checklist inside manual section */}
          <div className={styles.afterInstall}>
            <div className={styles.afterInstallTitle}>
              <i className="fas fa-check-double" /> Sau khi cài đặt
            </div>
            <div className={styles.verifySteps}>
              {[
                'Mở ứng dụng từ màn hình chính — giao diện sẽ không có thanh địa chỉ trình duyệt.',
                'Đăng nhập lại nếu được yêu cầu — hệ thống sẽ tự đăng ký nhận push notification.',
                'Bật thông báo ở cấp hệ thống nếu được hỏi (iOS: "Allow", Android: "Allow notifications").',
                'Thử nhận thông báo thử nghiệm từ Cài đặt → Thông báo để xác nhận.',
              ].map((item, idx) => (
                <div key={idx} className={styles.verifyItem}>
                  <i className={`fas fa-chevron-right ${styles.verifyIcon}`} />
                  <span>{item}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Troubleshooting */}
      <div className={styles.card}>
        <div className={styles.cardHeader}>
          <i className={`fas fa-tools ${styles.cardHeaderIcon}`} />
          <h2 className={styles.cardTitle}>Xử lý sự cố thường gặp</h2>
        </div>
        <div className={styles.cardBody}>
          <table className={styles.troubleshootTable}>
            <thead>
              <tr>
                <th style={{ width: '35%' }}>Vấn đề</th>
                <th style={{ width: '25%' }}>Nguyên nhân</th>
                <th>Cách khắc phục</th>
              </tr>
            </thead>
            <tbody>
              {troubleshootRows.map((row, idx) => (
                <tr key={idx}>
                  <td>{row.issue}</td>
                  <td>{row.cause}</td>
                  <td>{row.fix}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Related links */}
      <div className={styles.relatedLinks}>
        <span className={styles.relatedLabel}>Xem thêm:</span>
        <button className={styles.relatedLink} onClick={() => navigate('/notification-guide')}>
          <i className="fas fa-bell" /> Hướng dẫn Push Notification
        </button>
        <button className={styles.relatedLink} onClick={() => navigate('/faq')}>
          <i className="fas fa-question-circle" /> Câu hỏi thường gặp
        </button>
      </div>

      <button className={styles.backBtn} onClick={() => navigate('/help')}>
        <i className="fas fa-arrow-left" /> Quay lại Trợ giúp
      </button>
    </div>
  );
};
