import {
  linmLogo128,
  getAuthToken,
  getActiveCompanyCode,
  getSecureItem,
  removeSecureItem,
  setSecureItem,
  type SecureStorageConfig,
} from '@linm-soft-org/linm-web-common-components';
import { resolveShellIcon } from '../config/shellBranding';

const BRANDING_KEY = 'company_branding';

export interface CompanyBranding {
  /** Company code (tenant key) — same as `code`. */
  id?: string;
  code: string;
  name: string;
  shortName?: string;
  logoUrl?: string;
}

const BRANDING_CONFIG: SecureStorageConfig = {
  storageKey: BRANDING_KEY,
  version: 1,
  hashKey: 'company.branding',
};

export function normalizeCompanyCode(code: string): string {
  return code.trim().toUpperCase();
}

function parseLegacyBranding(raw: string): CompanyBranding | null {
  try {
    const parsed = JSON.parse(raw) as CompanyBranding;
    if (parsed && typeof parsed === 'object' && typeof parsed.code === 'string') {
      return parsed;
    }
  } catch {
    /* ignore */
  }
  return null;
}

export const companyBrandingService = {
  get(): CompanyBranding | null {
    const raw = getSecureItem<CompanyBranding>(BRANDING_CONFIG, {
      allowLegacyPlain: true,
      legacyParse: parseLegacyBranding,
    });
    return raw ?? null;
  },

  set(b: CompanyBranding): void {
    setSecureItem(BRANDING_CONFIG, b);
  },

  clear(): void {
    removeSecureItem(BRANDING_CONFIG);
  },

  /** Returns company logo, or /icons/{folder}/logo-128.png, or Linm default. */
  getInstallLogo(): string {
    return this.get()?.logoUrl ?? resolveShellIcon(linmLogo128);
  },

  /** Fetch by company code after login — domain API FallbackPolicy requires JWT. */
  async fetchByCode(code: string, apiUrl: string): Promise<CompanyBranding | null> {
    const normalized = normalizeCompanyCode(code);
    if (!normalized) return null;

    const token = getAuthToken();
    if (!token) return null;

    try {
      const headers: Record<string, string> = {
        Authorization: `Bearer ${token}`,
      };
      const company = getActiveCompanyCode();
      if (company) headers['X-Company-Id'] = company;

      const res = await fetch(`${apiUrl}/companies/by-code/${encodeURIComponent(normalized)}`, {
        headers,
      });
      if (!res.ok) return null;
      const json = (await res.json()) as { data?: Record<string, unknown> } & Record<string, unknown>;
      const data = (json.data ?? json) as {
        id?: string;
        code?: string;
        name: string;
        shortName?: string;
        logoUrl?: string;
      };
      const resolvedCode = normalizeCompanyCode(data.code ?? data.id ?? normalized);
      const branding: CompanyBranding = {
        id: resolvedCode,
        code: resolvedCode,
        name: data.name,
        shortName: data.shortName,
        logoUrl: data.logoUrl,
      };
      this.set(branding);
      return branding;
    } catch {
      return null;
    }
  },
};
