import {
  isLinmBrandChangeAllowed,
  linmLogo128,
  resolveSystemLogoSrc,
} from '@linm-soft-org/linm-web-common-components';

const trim = (value?: string) => (value ?? '').trim();

/** Default in-app icon — Linm.Web.Root/public/icons/logo-128.png */
export const SHELL_ICON_PATH = '/icons/logo-128.png';

const HEX_BG_COLOR = /#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})\b/g;

export type ShellBgColors = {
  bgColor1: string;
  bgColor2: string;
  /** CSS `background` — solid hex or `linear-gradient(135deg, bg1, bg2)`. */
  bgColor: string;
};

/** `#4facfe` (solid) or `#4facfe,#00f2fe` (login gradient). */
export function parseBgColorString(raw?: string): ShellBgColors {
  const hexes = trim(raw).match(HEX_BG_COLOR) || [];
  const bgColor1 = hexes[0] || '';
  const bgColor2 = hexes[1] || '';
  const bgColor = bgColor1
    ? (bgColor2 ? `linear-gradient(135deg, ${bgColor1} 0%, ${bgColor2} 100%)` : bgColor1)
    : '';
  return { bgColor1, bgColor2, bgColor };
}

export type ShellBrandingSnapshot = {
  title?: string;
  subTitle?: string;
  /** In-app logo URL (login · left rail · about) — not favicon/PWA tab */
  icon?: string;
  /** Domain subfolder under public/icons/, e.g. "ubna" */
  iconFolder?: string;
  /** Root bake `?v={build}` — bust HTTP cache of `/icons/*` after deploy. */
  assetQuery?: string;
  navMain?: string;
  allowChangeLinmLoading?: boolean;
  loadingIcon?: string;
  sidebarLogoSize?: number;
  sidebarIconOnly?: boolean;
  /** CSS background: solid hex or reconstructed gradient. */
  bgColor?: string;
  bgColor1?: string;
  bgColor2?: string;
};

declare global {
  interface Window {
    __LINM_SHELL_BRANDING__?: ShellBrandingSnapshot;
  }
}

/** Normalize "ubna" | "icons/ubna" | "/icons/ubna/" → "ubna" */
export function normalizeIconFolder(raw?: string): string {
  let v = trim(raw).replace(/^\/+|\/+$/g, '');
  if (v.toLowerCase().startsWith('icons/')) v = v.slice(6);
  if (!v || v.includes('..') || v.includes('/')) return '';
  return v;
}

/** In-app shell icon path — domain folder or root default. */
export function shellInAppIconUrl(folder?: string, file = 'logo-128.png'): string {
  const f = normalizeIconFolder(folder);
  return f ? `/icons/${f}/${file}` : `/icons/${file}`;
}

function readRootShellBranding(): ShellBrandingSnapshot | undefined {
  if (typeof window === 'undefined') return undefined;
  const value = window.__LINM_SHELL_BRANDING__;
  return value && typeof value === 'object' ? value : undefined;
}

/**
 * Build-time shell branding (VITE_*).
 * CI: vars.VITE_BV_ICON_FOLDER / VITE_ERP_ICON_FOLDER → VITE_ICON_FOLDER
 *     vars.VITE_{PREFIX}_BG_COLOR → VITE_BG_COLOR (`#hex` or `#bg1,#bg2`)
 */
export const shellBranding = {
  title: trim(import.meta.env.VITE_TITLE as string) || 'LINM ERP',
  subTitle: trim(import.meta.env.VITE_SUB_TITLE as string) || 'Hệ Thống Quản Trị Doanh Nghiệp',
  iconFolder: normalizeIconFolder(import.meta.env.VITE_ICON_FOLDER as string),
  navMain: trim(import.meta.env.VITE_NAV_MAIN as string) || 'Linm',
  ...parseBgColorString(import.meta.env.VITE_BG_COLOR as string),
} as const;

/**
 * In-app logo only (login · logout · nav · about). Favicon/PWA stay `/icons/*`.
 * Same Root gate as `resolveLogoLoadingConfig`: allow OFF → bundled linmBrand
 * (reject public `/icons`). Allow ON → common `resolveSystemLogoSrc`.
 */
function withShellAssetQuery(src: string): string {
  const q = trim(readRootShellBranding()?.assetQuery);
  if (!q || !src || src.startsWith('data:') || src.includes('?')) return src;
  if (src.indexOf('/icons/') === -1) return src;
  return `${src}${q}`;
}

export function resolveShellIcon(fallback: string = linmLogo128): string {
  if (!isLinmBrandChangeAllowed()) return linmLogo128;
  return withShellAssetQuery(resolveSystemLogoSrc() || fallback);
}

export function resolveShellNavMain(): string {
  const fromRoot = trim(readRootShellBranding()?.navMain);
  if (fromRoot) return fromRoot;
  return shellBranding.navMain;
}

/**
 * User-facing app name — Root `__LINM_SHELL_BRANDING__.navMain` then `VITE_NAV_MAIN`.
 * Never hardcode product (QLCV / RMMS) or domain folder (ubna).
 */
export function resolveAppName(): string {
  return resolveShellNavMain();
}

/** Replace `{AppName}` tokens from BFF help/FAQ copy. */
export function interpolateAppName(text: string, appName = resolveAppName()): string {
  if (!text) return text;
  return text.split('{AppName}').join(appName);
}

export function resolveShellTitle(): string {
  const fromRoot = trim(readRootShellBranding()?.title);
  if (fromRoot) return fromRoot;
  return shellBranding.title;
}

export function resolveShellSubTitle(): string {
  const fromRoot = trim(readRootShellBranding()?.subTitle);
  if (fromRoot) return fromRoot;
  return shellBranding.subTitle;
}

/** Login background CSS. Root snapshot first, then baked VITE_BG_COLOR string. Empty = default gradient. */
export function resolveShellBgColors(): ShellBgColors {
  const root = readRootShellBranding();
  const fromRoot = parseBgColorString(
    root?.bgColor1 && root?.bgColor2
      ? `${root.bgColor1},${root.bgColor2}`
      : root?.bgColor || root?.bgColor1,
  );
  if (fromRoot.bgColor1) return fromRoot;
  return {
    bgColor1: shellBranding.bgColor1,
    bgColor2: shellBranding.bgColor2,
    bgColor: shellBranding.bgColor,
  };
}

export function resolveShellBgColor(): string {
  return resolveShellBgColors().bgColor;
}

export function resolveSidebarIconOnly(): boolean {
  return readRootShellBranding()?.sidebarIconOnly === true;
}
