import { writePermissionsSnapshot } from '@linm-soft-org/linm-web-common-components';
import { DEV_MODULES } from './devRoutes';

/** Seed permission cache so ProtectedRoute + menu guards work without @linm/nav. */
export function seedStandalonePermissions(): void {
  const allowedPaths = [
    ...new Set(DEV_MODULES.flatMap((mod) => mod.routes.map((r) => r.url))),
  ];

  writePermissionsSnapshot({
    allowedPaths,
    navItems: allowedPaths.map((path) => ({ path })),
    packageDefaultUrl: '/dev',
  });
}
