/**
 * Help service facade.
 */

import {
  HelpCategory,
  SupportTicketCreate,
  ArticleFeedback,
  FAQ,
  HelpSearchResult,
} from '../../models/Help';
import { interpolateAppName } from '../../config/shellBranding';
import { helpEndpoint } from './endpoint';

function mapFaq(faq: FAQ): FAQ {
  return {
    ...faq,
    question: interpolateAppName(faq.question),
    answer: interpolateAppName(faq.answer),
  };
}

function mapSearch(result: HelpSearchResult): HelpSearchResult {
  return {
    ...result,
    title: interpolateAppName(result.title),
    description: interpolateAppName(result.description),
  };
}

export const helpService = {
  getArticles: (category?: HelpCategory, featured?: boolean) =>
    helpEndpoint.getArticles(category, featured),

  getArticle: (slug: string) => helpEndpoint.getArticle(slug),

  submitFeedback: (feedback: ArticleFeedback) => helpEndpoint.submitFeedback(feedback),

  search: async (query: string) => {
    const data = await helpEndpoint.search(query);
    return data.map(mapSearch);
  },

  getFAQs: async (category?: HelpCategory) => {
    const data = await helpEndpoint.getFAQs(category);
    return data
      .map(mapFaq)
      .sort((a, b) => a.order - b.order || a.question.localeCompare(b.question, 'vi'));
  },

  getWorkflows: () => helpEndpoint.getWorkflows(),

  getWorkflow: (type: 'ticket' | 'task' | 'incident') => helpEndpoint.getWorkflow(type),

  getVideos: (category?: HelpCategory) => helpEndpoint.getVideos(category),

  getCategories: () => helpEndpoint.getCategories(),

  submitSupportTicket: (ticket: SupportTicketCreate) =>
    helpEndpoint.submitSupportTicket(ticket),
};
