/** Clipboard text for tra cứu tài khoản — share login info with end users. */
export function buildAccountLookupCopyText(fullName: string, username: string): string {
  const displayName = fullName.trim() || username.trim();
  return [
    `Tài khoản: ${displayName}`,
    `UserName: ${username.trim()}`,
  ].join('\n');
}