import React, { useState, useEffect } from 'react';
import { HelpCategory, HelpCategoryInfo, getAllCategories } from '../../../models/Help';
import { helpService } from '../../../services/helpService';
import styles from './FAQCategoryFilter.module.css';

interface FAQCategoryFilterProps {
  selectedCategory?: HelpCategory;
  onCategoryChange: (category?: HelpCategory) => void;
}

export const FAQCategoryFilter: React.FC<FAQCategoryFilterProps> = ({
  selectedCategory,
  onCategoryChange,
}) => {
  const [categories, setCategories] = useState<HelpCategoryInfo[]>(() => getAllCategories());

  useEffect(() => {
    let cancelled = false;
    const timer = setTimeout(() => {
      helpService.getCategories()
        .then((data) => {
          if (!cancelled && data.length > 0) setCategories(data);
        })
        .catch(() => { /* keep static fallback */ });
    }, 0);
    return () => { cancelled = true; clearTimeout(timer); };
  }, []);

  return (
    <div className={styles.filter}>
      <button
        className={`${styles.filterButton} ${
          !selectedCategory ? styles.active : ''
        }`}
        onClick={() => onCategoryChange(undefined)}
      >
        Tất cả
      </button>
      {categories.map((category) => (
        <button
          key={category.id}
          className={`${styles.filterButton} ${
            selectedCategory === category.id ? styles.active : ''
          }`}
          onClick={() => onCategoryChange(category.id as HelpCategory)}
        >
          <i className={category.icon} />
          <span>{category.label}</span>
        </button>
      ))}
    </div>
  );
};
