import {
  getSecureItem,
  removeSecureItem,
  setSecureItem,
  type SecureStorageConfig,
} from '@linm-soft-org/linm-web-common-components';

const PWA_INSTALLED_KEY = 'pwa_installed';

const CONFIG: SecureStorageConfig = {
  storageKey: PWA_INSTALLED_KEY,
  version: 1,
  hashKey: 'pwa.installed',
};

export function isPwaInstalled(): boolean {
  return getSecureItem<string>(CONFIG, { allowLegacyPlain: true }) === '1';
}

export function markPwaInstalled(): void {
  setSecureItem(CONFIG, '1');
}

export function clearPwaInstalled(): void {
  removeSecureItem(CONFIG);
}
